Lemma tab_ok_upd : forall ws i s, 0 <= i < Z.of_nat (length ws) -> 0 <= s <= 8 -> tab_ok ws i ->
  tab_ok (upd ws (Z.to_nat i) (Z_to_bv 64 s)) (i + 1).
Proof.
