(* [comment removed for export] *)
Definition cnt_fill_exit (ra sp gp tp s0 s1 a2 a3 s3 s4 s6 s7 s8 s9 s10 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (tab : Z)
    : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a5' a6' a7' t3' t4' : word) (m' : mem) (ws' : list word),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (tab + 1024)) (Z_to_bv 64 256) a2 a3 (Z_to_bv 64 (tab + 1024)) a5' a6' a7'
                  (Z_to_bv 64 0) s3 s4 (Z_to_bv 64 tab) s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3' t4' t5 t6)
             F (Z_to_bv 64 0x12ded4) fc None m' (seg_rom asegs)
    /\ munch [(tab, tab + 1024)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u32arr asegs m' tab ws' /\ Z.of_nat (length ws') = 256 /\ tab_ok ws' 256.

(* [comment removed for export] *)
Lemma cnt_fill : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a4 a5 a6 a7 s2 s3 s4 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem) (tab : Z) (ws : list word),
  a0 = Z_to_bv 64 (tab + 4 * i) -> a1 = Z_to_bv 64 i -> a4 = Z_to_bv 64 (tab + 4 * i) -> s2 = Z_to_bv 64 (256 - i) ->
  Z.of_nat k = 256 - i -> 0 <= i -> (1 <= k)%nat ->
  0 < tab -> tab mod 16 = 0 -> tab + 1024 <= 2^47 -> (tab + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  u32arr asegs m tab ws -> Z.of_nat (length ws) = 256 -> tab_ok ws i ->
  acc asegs m tab 1024 -> mem_inv asegs m ->
  evt asegs (cnt_fill_exit ra sp gp tp s0 s1 (Z_to_bv 64 1) (Z_to_bv 64 1) s3 s4 s6 s7 s8 s9 s10 t5 t6 F fc m tab)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (Z_to_bv 64 1) (Z_to_bv 64 1) a4 a5 a6 a7
             s2 s3 s4 (Z_to_bv 64 tab) s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
        F (Z_to_bv 64 0x12de44) fc None m (seg_rom asegs)).
Proof.
